int mark = int.Parse(Console.ReadLine());
if (mark >= 70)
{
    Console.WriteLine("Distinction");
}
else if (mark >= 50)
{
    Console.WriteLine("Merit");
}
else if (mark >= 40)
{
    Console.WriteLine("Pass");
}
else
{
    Console.WriteLine("Not yet");
}

